/*  STEP 1 — COLLECT ENTERPRISE DATA
 *  In production these are six live connectors. For the PoC each
 *  block below stands in for one source system, with the same
 *  field shape the real connector would return.
 *
 *    projectSystem   -> Project / PSA platform  (plan, % complete, milestones)
 *    financeSystem   -> ERP / Finance           (budget, actuals, feed timestamp)
 *    resourceSystem  -> Resource Management     (roles, vacancies)
 *    raidLog         -> RAID register           (risks, issues, actions)
 *    priorReport     -> Document repository     (last approved report)
 *
 *  Four projects are seeded so that every branch of the workflow
 *  is exercised in a single run.
 */

const reportDate = '2026-09-06';
const reportingPeriod = '2026-W36';

const portfolio = [

  // ── 1. Complete data, genuinely troubled -> should draft a RED report
  {
    projectId: 'VCG-1184',
    projectName: 'Meridian Bank \u2014 Core Banking Modernisation',
    practice: 'Technology',
    engagementPartner: 'A. Raghavan',
    projectManager: 'S. Iyer',
    projectSystem: {
      plannedPctComplete: 62,
      actualPctComplete: 55,
      milestones: [
        { name: 'Mobilisation',             baseline: '2026-05-12', forecast: '2026-05-12', status: 'Complete' },
        { name: 'Current-state assessment', baseline: '2026-06-20', forecast: '2026-06-24', status: 'Complete' },
        { name: 'Target architecture',      baseline: '2026-07-18', forecast: '2026-07-25', status: 'Complete' },
        { name: 'UAT Cycle 1 sign-off',     baseline: '2026-08-24', forecast: '2026-09-07', status: 'At risk' },
        { name: 'Go-live readiness',        baseline: '2026-10-30', forecast: '2026-11-16', status: 'Not started' }
      ]
    },
    financeSystem: {
      budgetInr: 24000000,
      actualCostInr: 16800000,
      feedAsOf: '2026-09-05'
    },
    resourceSystem: {
      plannedFte: 14,
      actualFte: 12,
      vacancies: [ { role: 'Solution Architect', openDays: 21 } ]
    },
    raidLog: [
      { ref: 'R-07', type: 'Risk',  severity: 'High',   status: 'Open',   summary: 'Legacy data migration scope larger than assessed at mobilisation' },
      { ref: 'I-03', type: 'Issue', severity: 'High',   status: 'Open',   summary: 'Client SME availability below agreed allocation since mid-August' },
      { ref: 'R-11', type: 'Risk',  severity: 'Medium', status: 'Open',   summary: 'Third-party payment gateway certification timeline unconfirmed' },
      { ref: 'A-14', type: 'Action',severity: 'Medium', status: 'Overdue',summary: 'Confirm revised UAT entry criteria with client test lead' }
    ],
    priorReport: { period: '2026-W35', ragStatus: 'Amber', pctComplete: 52 },
    varianceExplained: true
  },

  // ── 2. Complete data, healthy -> should draft a GREEN report
  {
    projectId: 'VCG-1207',
    projectName: 'Kestrel Logistics \u2014 Network Cost Optimisation',
    practice: 'Supply Chain',
    engagementPartner: 'M. Fernandes',
    projectManager: 'D. Kulkarni',
    projectSystem: {
      plannedPctComplete: 40,
      actualPctComplete: 41,
      milestones: [
        { name: 'Mobilisation',        baseline: '2026-07-06', forecast: '2026-07-06', status: 'Complete' },
        { name: 'Baseline cost model', baseline: '2026-08-14', forecast: '2026-08-13', status: 'Complete' },
        { name: 'Scenario design',     baseline: '2026-09-25', forecast: '2026-09-25', status: 'In progress' },
        { name: 'Implementation plan', baseline: '2026-11-06', forecast: '2026-11-06', status: 'Not started' }
      ]
    },
    financeSystem: {
      budgetInr: 11000000,
      actualCostInr: 4200000,
      feedAsOf: '2026-09-04'
    },
    resourceSystem: {
      plannedFte: 6,
      actualFte: 6,
      vacancies: []
    },
    raidLog: [
      { ref: 'R-02', type: 'Risk', severity: 'Medium', status: 'Open', summary: 'Depot-level volume data quality varies across three regions' }
    ],
    priorReport: { period: '2026-W35', ragStatus: 'Green', pctComplete: 37 },
    varianceExplained: true
  },

  // ── 3. Finance feed stale -> should route to the MISSING DATA exception
  {
    projectId: 'VCG-1233',
    projectName: 'Northwind Retail \u2014 Store Operating Model',
    practice: 'Operations',
    engagementPartner: 'P. Sundaram',
    projectManager: 'R. Chandra',
    projectSystem: {
      plannedPctComplete: 28,
      actualPctComplete: 26,
      milestones: [
        { name: 'Mobilisation',       baseline: '2026-08-03', forecast: '2026-08-03', status: 'Complete' },
        { name: 'Store diagnostics',  baseline: '2026-09-18', forecast: '2026-09-18', status: 'In progress' },
        { name: 'Operating model v1', baseline: '2026-10-23', forecast: '2026-10-23', status: 'Not started' }
      ]
    },
    financeSystem: {
      budgetInr: 8500000,
      actualCostInr: null,          // ERP posting run failed
      feedAsOf: '2026-08-19'        // 18 days stale
    },
    resourceSystem: {
      plannedFte: 5,
      actualFte: 5,
      vacancies: []
    },
    raidLog: [
      { ref: 'R-01', type: 'Risk', severity: 'Low', status: 'Open', summary: 'Regional manager interview scheduling slower than planned' }
    ],
    priorReport: { period: '2026-W35', ragStatus: 'Green', pctComplete: 22 },
    varianceExplained: true
  },

  // ── 4. Complete data but no baseline + unexplained swing -> LOW CONFIDENCE
  {
    projectId: 'VCG-1251',
    projectName: 'Halcyon Pharma \u2014 R&D Portfolio Review',
    practice: 'Strategy',
    engagementPartner: 'N. Bhatt',
    projectManager: 'T. Menon',
    projectSystem: {
      plannedPctComplete: 15,
      actualPctComplete: 9,
      milestones: [
        { name: 'Mobilisation',      baseline: '2026-08-31', forecast: '2026-09-04', status: 'Complete' },
        { name: 'Pipeline data room',baseline: '2026-10-09', forecast: '2026-10-09', status: 'In progress' }
      ]
    },
    financeSystem: {
      budgetInr: 15000000,
      actualCostInr: 2850000,
      feedAsOf: '2026-09-04'
    },
    resourceSystem: {
      plannedFte: 8,
      actualFte: 7,
      vacancies: [ { role: 'Life Sciences SME', openDays: 9 } ]
    },
    raidLog: [
      { ref: 'R-04', type: 'Risk', severity: 'Medium', status: 'Open', summary: 'Scope of therapeutic areas in review not yet confirmed by client' }
    ],
    priorReport: null,              // first reporting cycle - no baseline
    varianceExplained: false        // cost run-rate swing has no logged cause
  }

];

return portfolio.map(p => ({
  json: { reportDate, reportingPeriod, ...p }
}));

/*  STEP 2 — VALIDATE DATA COMPLETENESS
 *  Gate before any analysis runs. The agent must never draft a
 *  status report on incomplete or stale source data.
 */

const STALENESS_LIMIT_DAYS = 7;

const p = $json;
const missing = [];

// Mandatory fields from each source system
if (p.projectSystem?.plannedPctComplete == null) missing.push('projectSystem.plannedPctComplete');
if (p.projectSystem?.actualPctComplete  == null) missing.push('projectSystem.actualPctComplete');
if (!p.projectSystem?.milestones?.length)        missing.push('projectSystem.milestones');
if (p.financeSystem?.budgetInr          == null) missing.push('financeSystem.budgetInr');
if (p.financeSystem?.actualCostInr      == null) missing.push('financeSystem.actualCostInr');
if (p.resourceSystem?.actualFte         == null) missing.push('resourceSystem.actualFte');
if (!Array.isArray(p.raidLog))                   missing.push('raidLog');

// Freshness check on the finance feed
const dayMs   = 86400000;
const feedAge = Math.round(
  (new Date(p.reportDate) - new Date(p.financeSystem?.feedAsOf ?? p.reportDate)) / dayMs
);
const stale = feedAge > STALENESS_LIMIT_DAYS;
if (stale) missing.push(`financeSystem.feedAsOf (stale by ${feedAge - STALENESS_LIMIT_DAYS}d)`);

return [{
  json: {
    ...p,
    financeFeedAgeDays: feedAge,
    missingFields: missing,
    dataComplete: missing.length === 0,
    validationNote: missing.length === 0
      ? 'All mandatory inputs present and within freshness tolerance.'
      : `Blocked: ${missing.length} input(s) missing or stale.`
  }
}];

/*  STEP 3 — DETECT VARIANCE, ANOMALIES AND CONFIDENCE
 *  All numbers the report will quote are computed HERE, deterministically.
 *  The language model is only allowed to narrate these figures - it is
 *  never asked to calculate. That is what keeps the agent auditable.
 */

const p = $json;
const dayMs = 86400000;

// ── Schedule performance
const spi = p.projectSystem.actualPctComplete / p.projectSystem.plannedPctComplete;
const schedulePctVariance = p.projectSystem.actualPctComplete - p.projectSystem.plannedPctComplete;

// ── Milestone slippage
const slipped = p.projectSystem.milestones
  .map(m => ({
    name: m.name,
    status: m.status,
    slipDays: Math.round((new Date(m.forecast) - new Date(m.baseline)) / dayMs)
  }))
  .filter(m => m.slipDays > 0);

const worstSlipDays = slipped.length ? Math.max(...slipped.map(m => m.slipDays)) : 0;

// ── Cost performance (earned value)
const earnedValueInr = p.financeSystem.budgetInr * (p.projectSystem.actualPctComplete / 100);
const cpi            = earnedValueInr / p.financeSystem.actualCostInr;
const costVarianceInr= Math.round(earnedValueInr - p.financeSystem.actualCostInr);
const budgetConsumedPct = +(100 * p.financeSystem.actualCostInr / p.financeSystem.budgetInr).toFixed(1);

// ── Resource position
const fteGap    = p.resourceSystem.plannedFte - p.resourceSystem.actualFte;
const vacancies = p.resourceSystem.vacancies ?? [];

// ── RAID position
const openHigh = p.raidLog.filter(r => r.severity === 'High'   && r.status === 'Open');
const overdue  = p.raidLog.filter(r => r.status === 'Overdue');

// ── RAG rules (deterministic, documented, auditable)
const redRule   = spi < 0.90 || cpi < 0.85 || worstSlipDays > 10 || openHigh.length >= 2;
const amberRule = spi < 0.97 || cpi < 0.95 || worstSlipDays > 3  || openHigh.length === 1 || fteGap > 0;
const ragStatus = redRule ? 'Red' : (amberRule ? 'Amber' : 'Green');

const ragMovement = p.priorReport
  ? (p.priorReport.ragStatus === ragStatus ? 'No change' : `${p.priorReport.ragStatus} \u2192 ${ragStatus}`)
  : 'No prior period';

// ── Confidence scoring — can the agent defend its own conclusion?
let confidence = 1.0;
const confidenceNotes = [];
if (!p.priorReport)             { confidence -= 0.30; confidenceNotes.push('no prior-period baseline'); }
if (!p.varianceExplained)       { confidence -= 0.25; confidenceNotes.push('cost/schedule variance has no logged cause'); }
if (p.financeFeedAgeDays > 3)   { confidence -= 0.10; confidenceNotes.push('finance feed older than 3 days'); }
if (p.projectSystem.milestones.length < 3) { confidence -= 0.10; confidenceNotes.push('fewer than 3 tracked milestones'); }
confidence = +Math.max(0, confidence).toFixed(2);

const CONFIDENCE_THRESHOLD = 0.65;

return [{
  json: {
    ...p,
    analysis: {
      spi: +spi.toFixed(3),
      cpi: +cpi.toFixed(3),
      schedulePctVariance,
      slippedMilestones: slipped,
      worstSlipDays,
      earnedValueInr: Math.round(earnedValueInr),
      costVarianceInr,
      budgetConsumedPct,
      fteGap,
      vacancies,
      openHighSeverity: openHigh,
      overdueActions: overdue,
      ragStatus,
      ragMovement
    },
    confidence,
    confidenceNotes,
    confidenceSufficient: confidence >= CONFIDENCE_THRESHOLD
  }
}];
